import{_ as r,C as e,o as s,c as d,E as a,a7 as l}from"./chunks/framework.FWlv_suP.js";const _=JSON.parse('{"title":"Qurio Data Deletion","description":"Instructions for deleting Qurio account and learning data.","frontmatter":{"title":"Qurio Data Deletion","description":"Instructions for deleting Qurio account and learning data."},"headers":[],"relativePath":"apps/qurio/data-deletion.md","filePath":"apps/qurio/data-deletion.md"}'),c={name:"apps/qurio/data-deletion.md"};function u(p,t,m,h,f,g){const o=e("AppBreadcrumbs"),n=e("AppSubnav"),i=e("CopyStandaloneUrl");return s(),d("div",null,[a(o,{"app-id":"qurio",current:"Data Deletion"}),a(n,{"app-id":"qurio"}),a(i,{path:"/data-deletion/qurio",label:"Copy standalone data-deletion URL","copied-label":"Data Deletion URL copied","document-name":"Qurio data-deletion page"}),t[0]||(t[0]=l('<h1 id="delete-qurio-data" tabindex="-1">Delete Qurio Data <a class="header-anchor" href="#delete-qurio-data" aria-label="Permalink to &quot;Delete Qurio Data&quot;">​</a></h1><h2 id="delete-your-account-in-qurio" tabindex="-1">Delete your account in Qurio <a class="header-anchor" href="#delete-your-account-in-qurio" aria-label="Permalink to &quot;Delete your account in Qurio&quot;">​</a></h2><p>Open <strong>Settings</strong>, select <strong>Delete my account</strong>, and enter the email address of the currently signed-in account to confirm permanent deletion. This action is available to Learner and Administrator accounts. Owner accounts cannot be self-deleted while they own Qurio; ownership must be transferred first.</p><p>The deletion request is authenticated and can delete only the currently signed-in account. It permanently deletes the Qurio Authentication account and its linked profile, account settings, learning progress, quiz attempts and answers, bookmarks, and exam-plan progress from the Supabase SQL database. Qurio also clears the deleted account&#39;s active local session and app-lock data from the installation that performs the deletion.</p><h2 id="what-may-remain" tabindex="-1">What may remain <a class="header-anchor" href="#what-may-remain" aria-label="Permalink to &quot;What may remain&quot;">​</a></h2><p>Minimal audit records may remain for security, abuse prevention, disputes, legal duties, and accountability. These records can include identifiers, actions, reasons, and timestamps. Support correspondence is separate from account data and may remain until it is deleted from the support mailbox.</p><p>A parent or guardian may request help deleting a child&#39;s account by emailing <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>. For support-correspondence deletion, email the same address from the address used for the original message.</p><h2 id="remove-local-device-data" tabindex="-1">Remove local device data <a class="header-anchor" href="#remove-local-device-data" aria-label="Permalink to &quot;Remove local device data&quot;">​</a></h2><p>Signing out only ends the session; it does not delete cloud account data. To remove local data without deleting an account, clear Qurio site storage and cookies in your browser. On Android, clear Qurio storage in system settings or uninstall it. This removes local session data, preferences, temporary cache, PIN verifier, Android Keystore-protected unlock material, notification-permission state, and scheduled reminders from that installation.</p><p>Disable reminders in Qurio and optionally revoke notification permission in Android settings.</p>',10))])}const b=r(c,[["render",u]]);export{_ as __pageData,b as default};
